/*
 * Tiny Dexie-compatible fallback for muLLM's chat store.
 * It implements only the subset used by chat.html and persists to localStorage.
 */
(function () {
  if (window.Dexie) return;

  function clone(value) {
    return JSON.parse(JSON.stringify(value));
  }

  class MiniCollection {
    constructor(table, items) {
      this.table = table;
      this.items = items || [];
    }
    async toArray() {
      return clone(this.items);
    }
    async sortBy(field) {
      return clone(this.items).sort((a, b) => {
        const av = a ? a[field] : undefined;
        const bv = b ? b[field] : undefined;
        if (av === bv) return 0;
        if (av == null) return -1;
        if (bv == null) return 1;
        return av < bv ? -1 : 1;
      });
    }
    reverse() {
      this.items = clone(this.items).reverse();
      return this;
    }
    async count() {
      return this.items.length;
    }
    async delete() {
      const ids = new Set(this.items.map((x) => x.id));
      const all = this.table._load().filter((x) => !ids.has(x.id));
      this.table._save(all);
    }
    async modify(fn) {
      const ids = new Set(this.items.map((x) => x.id));
      const all = this.table._load();
      for (const row of all) {
        if (ids.has(row.id)) fn(row);
      }
      this.table._save(all);
    }
  }

  class MiniWhere {
    constructor(table, field) {
      this.table = table;
      this.field = field;
    }
    equals(value) {
      return new MiniCollection(
        this.table,
        this.table._load().filter((row) => row && row[this.field] === value),
      );
    }
  }

  class MiniTable {
    constructor(db, name) {
      this.db = db;
      this.name = name;
    }
    _key() {
      return "mullm:dexie:" + this.db.name + ":" + this.name;
    }
    _load() {
      try {
        return JSON.parse(localStorage.getItem(this._key()) || "[]");
      } catch {
        return [];
      }
    }
    _save(rows) {
      localStorage.setItem(this._key(), JSON.stringify(rows));
    }
    async count() {
      return this._load().length;
    }
    async add(row) {
      const rows = this._load();
      const maxId = rows.reduce((m, x) => Math.max(m, Number(x.id) || 0), 0);
      const next = clone(row || {});
      next.id = next.id || maxId + 1;
      rows.push(next);
      this._save(rows);
      return next.id;
    }
    async toArray() {
      return clone(this._load());
    }
    async get(id) {
      const row = this._load().find((x) => x.id === id);
      return row ? clone(row) : undefined;
    }
    async update(id, changes) {
      const rows = this._load();
      let updated = 0;
      for (const row of rows) {
        if (row.id === id) {
          Object.assign(row, clone(changes || {}));
          updated++;
        }
      }
      this._save(rows);
      return updated;
    }
    async delete(id) {
      this._save(this._load().filter((x) => x.id !== id));
    }
    where(field) {
      return new MiniWhere(this, field);
    }
    orderBy(field) {
      const rows = this._load().sort((a, b) => {
        const av = a ? a[field] : undefined;
        const bv = b ? b[field] : undefined;
        if (av === bv) return 0;
        if (av == null) return -1;
        if (bv == null) return 1;
        return av < bv ? -1 : 1;
      });
      return new MiniCollection(this, rows);
    }
  }

  class MiniDexie {
    constructor(name) {
      this.name = name;
      this._tables = {};
    }
    version() {
      return {
        stores: (schema) => {
          for (const name of Object.keys(schema || {})) {
            this._tables[name] = new MiniTable(this, name);
            this[name] = this._tables[name];
          }
          return this;
        },
      };
    }
  }

  window.Dexie = MiniDexie;
})();
